INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM204PWIO', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'Which expression is equivalent to $(2x + 7)^2 - (2x - 3)(2x + 3)$?', NULL, $lyceon_json$[{"key":"A","text":"$28x + 40$"},{"key":"B","text":"$8x^2 + 28x + 58$"},{"key":"C","text":"$28x + 58$"},{"key":"D","text":"$28x + 46$"}]$lyceon_json$::jsonb, 'C', NULL, E'First, expand $(2x + 7)^2 = 4x^2 + 28x + 49$. Next, recognize $(2x - 3)(2x + 3)$ as a difference-of-squares pattern: $4x^2 - 9$. Subtracting gives $4x^2 + 28x + 49 - (4x^2 - 9) = 4x^2 + 28x + 49 - 4x^2 + 9 = 28x + 58$. The distractor $28x + 40$ results from distributing the negative sign incorrectly as $49 - 9 = 40$ instead of $49 + 9 = 58$. The distractor $8x^2 + 28x + 58$ results from adding the $4x^2$ terms instead of canceling them. The distractor $28x + 46$ results from an arithmetic error in computing $49 - 3 = 46$ instead of correctly handling the difference of squares to get $49 + 9$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
