INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22K8BJX', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'grid_in', E'If $4(3x - 7) + 11 = 2(5x + 9)$, what is the value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '17.5', ARRAY['35/2', '17.5'], E'Distributing on the left side: $4(3x - 7) + 11 = 12x - 28 + 11 = 12x - 17$. Distributing on the right side: $2(5x + 9) = 10x + 18$. Setting them equal: $12x - 17 = 10x + 18$. Subtracting $10x$ from both sides: $2x - 17 = 18$. Adding $17$ to both sides: $2x = 35$. Dividing by $2$: $x = \\frac{35}{2} = 17.5$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22Y2LES', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A bag contains 8 red marbles, 5 blue marbles, and 7 green marbles. If one marble is selected at random, what is the probability that it is blue?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{5}{13}$"},{"key":"B","text":"$\\frac{1}{4}$"},{"key":"C","text":"$\\frac{8}{20}$"},{"key":"D","text":"$\\frac{7}{20}$"}]$lyceon_json$::jsonb, 'B', NULL, E'The total number of marbles is $8 + 5 + 7 = 20$. The probability of selecting a blue marble is $\\frac{5}{20} = \\frac{1}{4}$. The answer $\\frac{5}{13}$ incorrectly excludes the blue marbles from the denominator. The answer $\\frac{8}{20}$ gives the probability of red instead of blue. The answer $\\frac{7}{20}$ gives the probability of green instead of blue.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23FQR50', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'What is the $y$-intercept of the line $5x - 2y = 30$?', NULL, $lyceon_json$[{"key":"A","text":"$(0, -15)$"},{"key":"B","text":"$(0, 15)$"},{"key":"C","text":"$(6, 0)$"},{"key":"D","text":"$(0, -6)$"}]$lyceon_json$::jsonb, 'A', NULL, E'Set $x = 0$: $-2y = 30$, so $y = -15$. The $y$-intercept is $(0, -15)$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24JU5O4', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'mcq', E'A freight company charges 83 dollars per shipment plus $\\frac{7}{4}$ dollars per pound. A competing company charges 47 dollars per shipment plus $\\frac{11}{4}$ dollars per pound. For what weight, in pounds, do the two companies charge the same total amount?', NULL, $lyceon_json$[{"key":"A","text":"$36$"},{"key":"B","text":"$9$"},{"key":"C","text":"$27$"},{"key":"D","text":"$48$"}]$lyceon_json$::jsonb, 'A', NULL, E'Let $w$ be the weight in pounds. Setting the charges equal: $83 + \\frac{7}{4}w = 47 + \\frac{11}{4}w$. Subtracting $\\frac{7}{4}w$ from both sides: $83 = 47 + \\frac{4}{4}w = 47 + w$. So $w = 83 - 47 = 36$. The value $9$ comes from dividing $36$ by $4$ instead of recognizing that $\\frac{11}{4} - \\frac{7}{4} = 1$. The value $27$ results from an arithmetic slip when subtracting $47$ from $83$ (getting $27$ instead of $36$ by a careless error, as it''s $83-56$). The value $48$ arises from setting up the equation with the rates added rather than subtracted.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM253AMDN', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'The equation $y = -1.3x + 94$ models the relationship between the number of absences, $x$, and the final grade, $y$, for students in a class. What is the best interpretation of the slope of this equation?', NULL, $lyceon_json$[{"key":"A","text":"For each additional absence, the predicted final grade decreases by $1.3$ points."},{"key":"B","text":"For each additional absence, the predicted final grade increases by $1.3$ points."},{"key":"C","text":"A student with no absences is predicted to have a final grade of $94$."},{"key":"D","text":"For each $1$-point increase in final grade, the number of absences decreases by $1.3$."}]$lyceon_json$::jsonb, 'A', NULL, E'The slope of $-1.3$ means that for each additional unit increase in $x$ (absences), the predicted value of $y$ (final grade) changes by $-1.3$, which is a decrease of $1.3$ points. The choice stating the grade increases by $1.3$ per absence ignores the negative sign of the slope. The choice about a student with no absences having a grade of $94$ correctly interprets the $y$-intercept, not the slope, so it answers a different question than what was asked. The choice reversing the variables confuses the roles of the independent and dependent variables, a concept gap about what slope represents in context.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25AA5CC', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'mcq', E'In triangle $ABC$, $AB = 13$, $BC = 11$, and the median from vertex $B$ to the midpoint $M$ of side $AC$ has length $BM = 8$. What is the length of $AC$? (Median length formula: $m_b^2 = \\frac{2a^2 + 2c^2 - b^2}{4}$, where $a$, $b$, $c$ are the sides opposite vertices $A$, $B$, $C$ respectively.)', NULL, $lyceon_json$[{"key":"A","text":"$12$"},{"key":"B","text":"$18$"},{"key":"C","text":"$20$"},{"key":"D","text":"$\\sqrt{580}$"}]$lyceon_json$::jsonb, 'B', NULL, E'The median from $B$ to the midpoint of $AC$ corresponds to side $b = AC$. Using the formula: $8^2 = \\frac{2(11)^2 + 2(13)^2 - AC^2}{4}$. This gives $64 = \\frac{242 + 338 - AC^2}{4} = \\frac{580 - AC^2}{4}$. Multiplying both sides by $4$: $256 = 580 - AC^2$, so $AC^2 = 324$ and $AC = 18$. The value $12$ results from an equation setup error such as omitting the factors of $2$ in the formula. The value $20$ comes from an arithmetic slip like computing $580 - 256 = 324$ correctly but then taking $\\sqrt{400}$ instead. The value $\\sqrt{580}$ is the result of forgetting to subtract $4m^2$ and returning $\\sqrt{2a^2 + 2c^2}$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25SFFJV', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'A nutritionist wants to study whether eating breakfast daily improves concentration among high school students. She recruits 200 student volunteers from three high schools. She allows each student to choose whether to eat breakfast every day for 8 weeks or to skip breakfast. At the end of the study, the breakfast group scores an average of 11 points higher on a concentration test than the no-breakfast group. A reporter writes: "Eating breakfast daily improves concentration in all high school students." Which of the following best identifies the flaw in the reporter''s claim?', NULL, $lyceon_json$[{"key":"A","text":"The sample size of 200 is too small to detect any difference in concentration."},{"key":"B","text":"Because students self-selected into groups and the sample consisted of volunteers from only three schools, the study cannot establish causation and the results may not generalize to all high school students."},{"key":"C","text":"The study should have lasted longer than 8 weeks for the results to be valid."},{"key":"D","text":"The concentration test is not a reliable measure of the effect of breakfast."}]$lyceon_json$::jsonb, 'B', NULL, E'There are two distinct flaws in the reporter''s claim. First, because students chose their own groups rather than being randomly assigned, confounding variables (such as motivation or health consciousness) may explain the difference, so causation cannot be established. Second, because the sample consists of volunteers from only three schools rather than a random sample of all high school students, the results cannot be generalized to all high school students. A sample of 200 is not inherently too small to detect a difference; sample size adequacy depends on effect size and variability. The 8-week duration is a design detail that does not address the fundamental issues of self-selection and limited generalizability. Questioning the reliability of the concentration test is speculative and not supported by the information given.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM281SENC', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'mcq', E'A line passes through the points $(-3, 11)$ and $(5, -13)$. Which of the following is an equation of the line?', NULL, $lyceon_json$[{"key":"A","text":"$y = -3x + 2$"},{"key":"B","text":"$y = 3x + 20$"},{"key":"C","text":"$y = -3x - 2$"},{"key":"D","text":"$y = 3x - 2$"}]$lyceon_json$::jsonb, 'A', NULL, E'The slope is $\\frac{-13 - 11}{5 - (-3)} = \\frac{-24}{8} = -3$. Using point-slope form with $(-3, 11)$: $y - 11 = -3(x + 3) = -3x - 9$, so $y = -3x + 2$. The equation $y = 3x + 20$ arises from using $3$ instead of $-3$ for the slope and then computing a consistent but incorrect intercept. The equation $y = -3x - 2$ gets the correct slope but makes an arithmetic error when evaluating $11 - 9$ as $-2$ instead of $+2$. The equation $y = 3x - 2$ reverses the sign of the slope and also miscalculates the intercept.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28B7X9U', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has a diameter of $42$ centimeters. What is the circumference of the circle, in centimeters?', NULL, $lyceon_json$[{"key":"A","text":"$21\\pi$"},{"key":"B","text":"$42\\pi$"},{"key":"C","text":"$441\\pi$"},{"key":"D","text":"$84\\pi$"}]$lyceon_json$::jsonb, 'B', NULL, E'The circumference of a circle is $C = \\pi d$, where $d$ is the diameter. With $d = 42$: $C = 42\\pi$. The value $21\\pi$ results from halving the diameter to get the radius but then using $\\pi r$ instead of $2\\pi r$, reflecting confusion between the radius and diameter formulas. The value $441\\pi$ comes from computing the area $\\pi r^2 = \\pi(21)^2 = 441\\pi$ instead of the circumference. The value $84\\pi$ arises from incorrectly using $2\\pi d$ instead of $\\pi d$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28BSCGT', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $h(x) = -2(x - 5)^2 + 18$ models the height of a projectile in feet. What is the maximum value of $h(x)$?', NULL, $lyceon_json$[{"key":"A","text":"$-5$"},{"key":"B","text":"$5$"},{"key":"C","text":"$18$"},{"key":"D","text":"$-18$"}]$lyceon_json$::jsonb, 'C', NULL, E'The function is in vertex form $a(x - h)^2 + k$ with $a = -2$, $h = 5$, and $k = 18$. Since $a < 0$, the parabola opens downward and the vertex $(5, 18)$ is the maximum point. The maximum value of $h(x)$ is the $y$-coordinate of the vertex, which is $18$. The distractor $-5$ results from misreading the vertex form and taking $-h$ instead of $k$. The distractor $5$ results from identifying the $x$-coordinate of the vertex rather than the maximum output value. The distractor $-18$ results from applying a sign error to the $k$ value.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28H6LOC', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'grid_in', E'A jacket originally costs $85$ dollars. If the store offers a $20\\%$ discount, what is the sale price, in dollars?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '68', ARRAY['68'], E'A $20\\%$ discount on $85$ dollars is $0.20 \\times 85 = 17$ dollars. The sale price is $85 - 17 = 68$ dollars.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2981UEX', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'Which of the following values of $x$ satisfies the inequality $5x - 17 > 23$?', NULL, $lyceon_json$[{"key":"A","text":"$6$"},{"key":"B","text":"$8$"},{"key":"C","text":"$7$"},{"key":"D","text":"$11$"}]$lyceon_json$::jsonb, 'D', NULL, E'Add 17 to both sides: $5x > 40$. Divide by 5: $x > 8$. Testing each value: $x = 6$ gives $5(6) - 17 = 13$, not greater than 23. $x = 8$ gives $5(8) - 17 = 23$, not strictly greater. $x = 7$ gives $5(7) - 17 = 18$, not greater than 23. $x = 11$ gives $5(11) - 17 = 38 > 23$, which satisfies the inequality.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AJUF1O', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'grid_in', E'A researcher collects data on the age (in years) and value (in thousands of dollars) of $8$ used cars of the same model. The line of best fit is $v = -2.9a + 31.4$, where $a$ is the age and $v$ is the predicted value in thousands of dollars. One car is $7$ years old and has an actual value of $12.8$ thousand dollars. What is the residual for this car, in thousands of dollars?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '1.7', ARRAY['17/10', '1.7'], E'The predicted value for a $7$-year-old car is $v = -2.9(7) + 31.4 = -20.3 + 31.4 = 11.1$ thousand dollars. The residual is the actual value minus the predicted value: $12.8 - 11.1 = 1.7$ thousand dollars. A positive residual means the car''s actual value is above the value predicted by the line of best fit.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ARONKB', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'mcq', E'A hemispherical bowl with an inner radius of $7$ cm is completely filled with water. The water is then poured into a right circular cylindrical container with an inner radius of $4$ cm. What is the height of the water in the cylindrical container, in centimeters? (Volume of a sphere: $V = \\frac{4}{3}\\pi r^3$.)', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{343}{24}$"},{"key":"B","text":"$\\frac{343}{48}$"},{"key":"C","text":"$\\frac{343}{12}$"},{"key":"D","text":"$\\frac{49}{6}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The volume of a hemisphere is $\\frac{1}{2} \\cdot \\frac{4}{3}\\pi r^3 = \\frac{2}{3}\\pi r^3$. With $r = 7$: $V = \\frac{2}{3}\\pi(343) = \\frac{686\\pi}{3}$. Setting this equal to the cylinder volume $\\pi(4^2)h = 16\\pi h$: $16h = \\frac{686}{3}$, so $h = \\frac{686}{48} = \\frac{343}{24}$. The value $\\frac{343}{48}$ results from using $\\frac{1}{3}\\pi r^3$ instead of $\\frac{2}{3}\\pi r^3$, reflecting confusion about the hemisphere formula. The value $\\frac{343}{12}$ comes from using the full sphere volume $\\frac{4}{3}\\pi(343)$ instead of halving it. The value $\\frac{49}{6}$ arises from using $r^2 = 49$ instead of $r^3 = 343$ in the volume formula and dividing by the cylinder radius $4$ instead of $r^2 = 16$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BGQOTQ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'mcq', E'A data set contains $11$ values. When the values are arranged in increasing order, the median is $34$ and the mean is $37$. The smallest value in the data set is replaced by a value that is $18$ less than the original smallest value. Which of the following correctly describes the effect on the median and the mean?', NULL, $lyceon_json$[{"key":"A","text":"The median decreases and the mean decreases."},{"key":"B","text":"The median stays the same and the mean decreases."},{"key":"C","text":"The median decreases and the mean stays the same."},{"key":"D","text":"Both the median and the mean stay the same."}]$lyceon_json$::jsonb, 'B', NULL, E'With $11$ values, the median is the $6$th value in order. Replacing the smallest value with something even smaller does not change the $6$th value, so the median stays the same. However, the sum of all values decreases by $18$, so the mean decreases by $\\frac{18}{11}$. The choice stating both decrease incorrectly assumes the median is affected by extreme values. The choice stating the median decreases and the mean stays the same reverses the correct effects. The choice stating both stay the same misreads the impact of changing a data point on the sum and therefore the mean.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CJGV14', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'grid_in', E'Line $p$ has the equation $7x + 3y = 41$. Line $q$ is perpendicular to line $p$ and passes through the point $(7, -2)$. What is the $y$-coordinate of the point where line $q$ crosses the $y$-axis?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-5', ARRAY['-5'], E'Rewriting line $p$ in slope-intercept form: $3y = -7x + 41$, so $y = -\\frac{7}{3}x + \\frac{41}{3}$. The slope of line $p$ is $-\\frac{7}{3}$. A line perpendicular to $p$ has slope equal to the negative reciprocal, which is $\\frac{3}{7}$. Using point-slope form with the point $(7, -2)$: $y - (-2) = \\frac{3}{7}(x - 7)$, giving $y + 2 = \\frac{3}{7}x - 3$, so $y = \\frac{3}{7}x - 5$. At the $y$-axis, $x = 0$, so $y = -5$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CLKYFU', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'mcq', E'The mean of six measurements is $47$. A seventh measurement of $68$ is added to the data set. What is the mean of all seven measurements?', NULL, $lyceon_json$[{"key":"A","text":"$50$"},{"key":"B","text":"$51$"},{"key":"C","text":"$53$"},{"key":"D","text":"$57.5$"}]$lyceon_json$::jsonb, 'A', NULL, E'The sum of the original six measurements is $6 \\times 47 = 282$. Adding the seventh measurement gives a total of $282 + 68 = 350$. The new mean is $\\frac{350}{7} = 50$. The value $51$ results from an arithmetic slip such as computing $282 + 68 = 351$, giving $\\frac{351}{7} \\approx 50.1$ and rounding to $51$. The value $53$ comes from dividing by $6$ instead of $7$ after adding the new measurement ($\\frac{350}{6} \\approx 58.3$) or from a different division error. The value $57.5$ results from simply averaging $47$ and $68$ ($\\frac{47 + 68}{2} = 57.5$), incorrectly treating the original mean and the new value as two equally weighted data points.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FL618Y', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'mcq', E'In a school election, candidate $X$ received $42\\%$ of the votes and candidate $Y$ received $31\\%$ of the votes. The remaining votes went to candidate $Z$. If candidate $Z$ received $189$ votes, how many total votes were cast in the election?', NULL, $lyceon_json$[{"key":"A","text":"$630$"},{"key":"B","text":"$650$"},{"key":"C","text":"$700$"},{"key":"D","text":"$750$"}]$lyceon_json$::jsonb, 'C', NULL, E'Candidate $Z$ received $100\\% - 42\\% - 31\\% = 27\\%$ of the votes. If $27\\%$ of the total equals $189$, then the total is $\\frac{189}{0.27} = 700$ votes. The value $630$ comes from dividing $189$ by $0.30$ (rounding $27\\%$ to $30\\%$), an equation setup error. The value $650$ results from a slip such as computing $\\frac{189}{0.29} \\approx 652$ and rounding to $650$. The value $750$ results from subtracting only one candidate''s share (using $100\\% - 42\\% = 58\\%$ or $100\\% - 31\\% = 69\\%$) and computing incorrectly.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2G8DMKH', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'In triangle $PQR$, the measure of angle $P$ is $43°$ and the measure of angle $Q$ is $71°$. What is the measure, in degrees, of angle $R$?', NULL, $lyceon_json$[{"key":"A","text":"$66°$"},{"key":"B","text":"$67°$"},{"key":"C","text":"$114°$"},{"key":"D","text":"$46°$"}]$lyceon_json$::jsonb, 'A', NULL, E'The sum of the interior angles of a triangle is $180°$. Therefore, angle $R = 180° - 43° - 71° = 66°$. The value $67°$ results from an arithmetic slip in the subtraction. The value $114°$ comes from subtracting only one angle from $180°$ ($180° - 66°$), reflecting a misunderstanding of the angle-sum property. The value $46°$ arises from computing $71° - 43° + 18°$ or a similar misread of the problem.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GBV63Q', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'mcq', E'A surveyor stands at point $A$ and measures the angle of elevation to the top of a tower at point $C$ to be $29°$. She walks $40$ meters directly toward the tower to point $B$, where the angle of elevation to $C$ is $53°$. What is the height of the tower, to the nearest meter? (Use $\\tan(29°) \\approx 0.5543$ and $\\tan(53°) \\approx 1.3270$.)', NULL, $lyceon_json$[{"key":"A","text":"$38$ meters"},{"key":"B","text":"$29$ meters"},{"key":"C","text":"$22$ meters"},{"key":"D","text":"$53$ meters"}]$lyceon_json$::jsonb, 'A', NULL, E'Let $h$ be the tower height and $d$ be the horizontal distance from $B$ to the base. From $B$: $\\tan(53°) = \\frac{h}{d}$, so $h = 1.3270d$. From $A$ (which is $40$ m farther): $\\tan(29°) = \\frac{h}{d + 40}$, so $h = 0.5543(d + 40)$. Setting equal: $1.3270d = 0.5543d + 22.172$, giving $0.7727d = 22.172$ and $d \\approx 28.69$. Then $h = 1.3270 \\times 28.69 \\approx 38.07 \\approx 38$ meters. The value $29$ meters comes from reporting the intermediate value of $d$ (the horizontal distance) instead of the height $h$. The value $22$ meters results from computing only $\\tan(29°) \\times 40 = 22.17$ and stopping. The value $53$ meters arises from an arithmetic error such as adding $d$ and a miscomputed $h$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GOD427', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'grid_in', E'A delivery truck can carry at most 1,150 pounds. Each crate of type P weighs 47 pounds and each crate of type Q weighs 31 pounds. If the truck is already loaded with 9 crates of type P, what is the maximum number of whole crates of type Q that can still be loaded onto the truck?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '23', ARRAY['23'], E'The 9 crates of type P weigh $9 \\times 47 = 423$ pounds. The remaining capacity is $1{,}150 - 423 = 727$ pounds. Each type Q crate weighs 31 pounds, so the number of type Q crates satisfies $31Q \\leq 727$. Dividing gives $Q \\leq \\frac{727}{31} \\approx 23.45$. Since $Q$ must be a whole number, the maximum is $23$. A common error is to round up to $24$, but $24 \\times 31 = 744$, which exceeds the remaining capacity of $727$ pounds.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2H3W36Y', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'A farmer has at most 370 dollars to spend on seed bags. Large bags cost 29 dollars each and small bags cost 11 dollars each. If the farmer buys $L$ large bags and $S$ small bags, which inequality represents this constraint?', NULL, $lyceon_json$[{"key":"A","text":"$29L + 11S \\leq 370$"},{"key":"B","text":"$29L + 11S \\geq 370$"},{"key":"C","text":"$11L + 29S \\leq 370$"},{"key":"D","text":"$29L + 11S < 370$"}]$lyceon_json$::jsonb, 'A', NULL, E'The total cost is $29L + 11S$, and the farmer can spend at most 370 dollars, meaning the total must be less than or equal to 370. This gives $29L + 11S \\leq 370$. The inequality $29L + 11S \\geq 370$ reverses the direction, incorrectly requiring spending at least 370 dollars. The expression $11L + 29S \\leq 370$ swaps the coefficients, assigning the wrong price to each bag type. The strict inequality $29L + 11S < 370$ excludes spending exactly 370 dollars, but ''at most'' includes equality.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HHUMOM', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'grid_in', E'A rectangle has a length of $19$ centimeters and a width of $11$ centimeters. What is the area of the rectangle, in square centimeters?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '209', ARRAY['209'], E'The area of a rectangle is length times width: $19 \\times 11 = 209$ square centimeters.', NULL, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HX52WN', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'mcq', E'The equation $x^2 + y^2 + 4x - 6y - 39 = 0$ defines a circle. What is the slope of the line tangent to this circle at the point $(4, 7)$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{2}{3}$"},{"key":"B","text":"$-\\frac{3}{2}$"},{"key":"C","text":"$\\frac{3}{2}$"},{"key":"D","text":"$-\\frac{2}{3}$"}]$lyceon_json$::jsonb, 'B', NULL, E'Complete the square: $x^2 + 4x + 4 + y^2 - 6y + 9 = 39 + 4 + 9 = 52$, giving $(x + 2)^2 + (y - 3)^2 = 52$. The center is $(-2, 3)$. The slope of the radius from $(-2, 3)$ to the tangent point $(4, 7)$ is $\\frac{7 - 3}{4 - (-2)} = \\frac{4}{6} = \\frac{2}{3}$. Since a tangent line is perpendicular to the radius at the point of tangency, the tangent slope is the negative reciprocal: $-\\frac{3}{2}$. The value $\\frac{2}{3}$ results from using the radius slope directly, confusing the radius direction with the tangent direction. The value $\\frac{3}{2}$ comes from taking the reciprocal without negating it. The value $-\\frac{2}{3}$ arises from simply negating the radius slope without taking the reciprocal.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2I2I7V5', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'A polling organization surveys two independent random samples from the same population of 12,000 university alumni. Sample A consists of 600 alumni and yields a proportion of 0.41 who donated in the past year, with a margin of error of 0.039. Sample B consists of 1,500 alumni and yields a proportion of 0.38 who donated, with a margin of error of 0.025. Which of the following statements is supported by these results?', NULL, $lyceon_json$[{"key":"A","text":"The true proportion of alumni who donated is closer to 0.41 because Sample A was conducted first."},{"key":"B","text":"The confidence intervals from the two samples do not overlap, so the results are contradictory."},{"key":"C","text":"Sample B provides a more precise estimate of the true proportion because its margin of error is smaller."},{"key":"D","text":"Since the two samples give different proportions, neither estimate is reliable."}]$lyceon_json$::jsonb, 'C', NULL, E'Sample B has a larger sample size (1,500 vs. 600), which produces a smaller margin of error (0.025 vs. 0.039) and therefore a more precise estimate. The order of sampling is irrelevant to the accuracy of either estimate. The confidence intervals actually overlap: Sample A gives $(0.371, 0.449)$ and Sample B gives $(0.355, 0.405)$, so claiming they do not overlap is arithmetically incorrect. Concluding that neither estimate is reliable because they differ ignores that sampling variability naturally produces different sample proportions, and both intervals are consistent with each other.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IVINRG', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'A wildlife researcher tracks the population of a certain bird species at a nature reserve. The population can be modeled by the function $P(t) = 347 - 13t$, where $t$ is the number of years after the study began. What does the number $13$ represent in this context?', NULL, $lyceon_json$[{"key":"A","text":"The population decreases by 13 birds each year."},{"key":"B","text":"The initial population is 13 birds."},{"key":"C","text":"The population increases by 13 birds each year."},{"key":"D","text":"After 13 years, the population reaches zero."}]$lyceon_json$::jsonb, 'A', NULL, E'In the function $P(t) = 347 - 13t$, the coefficient of $t$ is $-13$, representing the rate of change of the population per year. Because it is negative, the population decreases by 13 birds each year. Interpreting 13 as the initial population confuses the coefficient of $t$ with the constant term $347$. Stating the population increases by 13 ignores the subtraction sign in the model. Claiming the population reaches zero after 13 years misreads the question, which asks about the meaning of the number 13 rather than when the population vanishes; the population reaches zero at $t = \\frac{347}{13} \\approx 26.7$ years.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2K6C1YZ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A map uses a scale of $3$ centimeters to $17$ miles. Two towns are $11.4$ centimeters apart on the map. What is the actual distance, in miles, between the two towns?', NULL, $lyceon_json$[{"key":"A","text":"$57.8$"},{"key":"B","text":"$64.6$"},{"key":"C","text":"$68.4$"},{"key":"D","text":"$34.2$"}]$lyceon_json$::jsonb, 'B', NULL, E'Using the scale, $\\frac{3 \\text{ cm}}{17 \\text{ miles}} = \\frac{11.4 \\text{ cm}}{x \\text{ miles}}$. Cross-multiplying gives $3x = 17 \\times 11.4 = 193.8$, so $x = 64.6$ miles. The value $57.8$ comes from miscomputing $11.4 \\div 3$ as $3.4$ instead of $3.8$, then multiplying $3.4 \\times 17 = 57.8$. The value $68.4$ comes from rounding $\\frac{17}{3}$ to $6$ and computing $6 \\times 11.4 = 68.4$ instead of $5.\\overline{6} \\times 11.4$. The value $34.2$ comes from multiplying $3 \\times 11.4 = 34.2$ without completing the proportion, an equation setup error.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KEJ6DB', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'A survey of 200 employees at a company recorded whether each employee works remotely or in the office and whether each employee has been with the company for more than 5 years or 5 years or fewer. Of the 200 employees, 74 work remotely. Of the 74 remote employees, 31 have been with the company for more than 5 years. Of the 126 office employees, 58 have been with the company for more than 5 years. If an employee who has been with the company for more than 5 years is selected at random, what is the probability that this employee works remotely?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{31}{74}$"},{"key":"B","text":"$\\frac{31}{89}$"},{"key":"C","text":"$\\frac{31}{200}$"},{"key":"D","text":"$\\frac{58}{89}$"}]$lyceon_json$::jsonb, 'B', NULL, E'The total number of employees with more than 5 years is $31 + 58 = 89$. Among these, 31 work remotely, so the probability is $\\frac{31}{89}$. The value $\\frac{31}{74}$ incorrectly conditions on remote employees rather than on employees with more than 5 years. The value $\\frac{31}{200}$ divides by the total number of employees instead of conditioning on tenure. The value $\\frac{58}{89}$ gives the probability that an employee with more than 5 years works in the office, which answers the wrong question.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KZYQVD', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'grid_in', E'A circle has center $(-2, 5)$ and passes through the point $(1, 3)$. The area of the circle can be written as $k\\pi$ square units. What is the value of $k$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '13', ARRAY['13'], E'The radius is the distance from the center $(-2, 5)$ to the point $(1, 3)$: $r = \\sqrt{(1 - (-2))^2 + (3 - 5)^2} = \\sqrt{3^2 + (-2)^2} = \\sqrt{9 + 4} = \\sqrt{13}$. The area is $\\pi r^2 = \\pi(\\sqrt{13})^2 = 13\\pi$. Therefore $k = 13$. A common error is reporting the radius $\\sqrt{13}$ instead of squaring it, or making a sign error in the distance formula to get $\\sqrt{5}$ and an area of $5\\pi$.', NULL, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LZISZL', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following is equivalent to $7x^3 \\cdot 3x^5$?', NULL, $lyceon_json$[{"key":"A","text":"$10x^8$"},{"key":"B","text":"$21x^8$"},{"key":"C","text":"$21x^{15}$"},{"key":"D","text":"$10x^{15}$"}]$lyceon_json$::jsonb, 'B', NULL, E'When multiplying monomials, multiply the coefficients and add the exponents of like bases. The coefficients $7 \\cdot 3 = 21$, and the exponents $3 + 5 = 8$, giving $21x^8$. The distractor $10x^8$ results from adding the coefficients ($7 + 3 = 10$) instead of multiplying them. The distractor $21x^{15}$ results from multiplying the exponents ($3 \\cdot 5 = 15$) instead of adding them. The distractor $10x^{15}$ combines both errors: adding coefficients and multiplying exponents.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2M193JF', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'grid_in', E'The function $f(x) = a(x - h)^2 + k$ has its vertex at $(3, -1)$ and passes through the point $(1, 7)$. What is the value of $f(0)$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '17', ARRAY['17'], E'Since the vertex is at $(3, -1)$, the function has the form $f(x) = a(x - 3)^2 - 1$. Substituting the point $(1, 7)$: $7 = a(1 - 3)^2 - 1 = 4a - 1$. Solving gives $4a = 8$, so $a = 2$. Therefore $f(x) = 2(x - 3)^2 - 1$. Evaluating at $x = 0$: $f(0) = 2(0 - 3)^2 - 1 = 2(9) - 1 = 18 - 1 = 17$.', NULL, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MAJ5I7', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'mcq', E'In a class of 150 students, each student studies exactly one foreign language: French, Mandarin, or Arabic. There are 53 students studying French, 62 studying Mandarin, and 35 studying Arabic. Of the French students, 17 are also in the debate club. Of the Mandarin students, 29 are in the debate club. Of the Arabic students, 11 are in the debate club. A student from the class is selected at random. Given that the selected student is NOT in the debate club, what is the probability that the student studies Mandarin?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{33}{93}$"},{"key":"B","text":"$\\frac{62}{150}$"},{"key":"C","text":"$\\frac{29}{57}$"},{"key":"D","text":"$\\frac{33}{150}$"}]$lyceon_json$::jsonb, 'A', NULL, E'First, find the number of students NOT in the debate club: $150 - (17 + 29 + 11) = 150 - 57 = 93$. Among those not in the debate club, the number studying Mandarin is $62 - 29 = 33$. The conditional probability is $\\frac{33}{93}$. The value $\\frac{62}{150}$ ignores the condition entirely and gives the unconditional probability of studying Mandarin. The value $\\frac{29}{57}$ conditions on being IN the debate club rather than NOT in the debate club. The value $\\frac{33}{150}$ uses the correct numerator of 33 but divides by the total class size instead of conditioning on not being in the debate club.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MJ5F9N', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'The function $g$ is defined by $g(x) = 8x - 23$. What is the value of $g(5)$?', NULL, $lyceon_json$[{"key":"A","text":"$17$"},{"key":"B","text":"$63$"},{"key":"C","text":"$-17$"},{"key":"D","text":"$15$"}]$lyceon_json$::jsonb, 'A', NULL, E'Substitute $x = 5$: $g(5) = 8(5) - 23 = 40 - 23 = 17$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2N5Z2LO', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'If $g(x) = 2x^2 - 11x + 5$, what is the value of $g(4)$?', NULL, $lyceon_json$[{"key":"A","text":"$-7$"},{"key":"B","text":"$7$"},{"key":"C","text":"$-17$"},{"key":"D","text":"$81$"}]$lyceon_json$::jsonb, 'A', NULL, E'Substitute $x = 4$: $g(4) = 2(4)^2 - 11(4) + 5 = 2(16) - 44 + 5 = 32 - 44 + 5 = -7$. The distractor $7$ results from dropping the negative sign in the final computation ($44 - 32 - 5 = 7$ or similar sign mishandling). The distractor $-17$ results from subtracting the constant $5$ instead of adding it: $32 - 44 - 5 = -17$. The distractor $81$ results from adding all terms as positive: $32 + 44 + 5 = 81$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NRRFDU', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'mcq', E'A factory uses $13$ liters of chemical $P$ for every $9$ liters of chemical $Q$ to produce a solution. In a batch that requires $286$ liters of the solution, how many liters of chemical $Q$ are needed?', NULL, $lyceon_json$[{"key":"A","text":"$117$"},{"key":"B","text":"$126$"},{"key":"C","text":"$143$"},{"key":"D","text":"$169$"}]$lyceon_json$::jsonb, 'A', NULL, E'The ratio of $P$ to $Q$ is $13{:}9$, so the total parts are $13 + 9 = 22$. The fraction that is chemical $Q$ is $\\frac{9}{22}$. Therefore $Q = \\frac{9}{22} \\times 286 = \\frac{2574}{22} = 117$ liters. The value $126$ results from setting up $\\frac{9}{13} \\times 286 \\div 2 \\approx 99$ and then adding incorrectly, or from computing $\\frac{9}{22} \\times 308$ by using a wrong total. The value $143$ comes from dividing $286$ by $2$, treating the two chemicals as equal parts. The value $169$ results from computing the amount of chemical $P$ instead ($\\frac{13}{22} \\times 286 = 169$), confusing which chemical was asked for.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NZHNXL', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'mcq', E'A store marks up a product by $40\\%$ over its wholesale cost and then offers a $25\\%$ discount on the marked-up price during a sale. If the sale price is $84$ dollars, what is the wholesale cost, in dollars?', NULL, $lyceon_json$[{"key":"A","text":"$48$"},{"key":"B","text":"$60$"},{"key":"C","text":"$80$"},{"key":"D","text":"$112$"}]$lyceon_json$::jsonb, 'C', NULL, E'Let the wholesale cost be $w$. After a $40\\%$ markup, the marked price is $1.4w$. After a $25\\%$ discount, the sale price is $0.75 \\times 1.4w = 1.05w$. Setting $1.05w = 84$ gives $w = \\frac{84}{1.05} = 80$ dollars. The value $48$ results from treating both operations as markups and dividing $84$ by $1.4 \\times 1.25 = 1.75$, an equation setup error. The value $60$ comes from dividing $84$ by $1.4$ alone, reversing only the markup and ignoring the discount step. The value $112$ results from dividing $84$ by $0.75$ alone, obtaining the marked-up price rather than the wholesale cost, a concept gap about which step the result represents.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
