INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QRG9LW', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'mcq', E'What value of $x$ satisfies the equation $13x - 29 = 49$?', NULL, $lyceon_json$[{"key":"A","text":"$6$"},{"key":"B","text":"$-6$"},{"key":"C","text":"$\\frac{20}{13}$"},{"key":"D","text":"$7$"}]$lyceon_json$::jsonb, 'A', NULL, E'Add 29 to both sides: $13x = 78$. Divide both sides by 13: $x = 6$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2R2MO1B', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A researcher wants to estimate the mean commute time, in minutes, for employees at a large company with 8,000 employees. She takes a random sample of 250 employees and finds a mean commute time of 37 minutes with a margin of error of 3 minutes at a 95% confidence level. Which of the following conclusions is best supported by this information?', NULL, $lyceon_json$[{"key":"A","text":"Approximately 95% of the 250 sampled employees have a commute time between 34 and 40 minutes."},{"key":"B","text":"The researcher is 95% confident that the mean commute time for all 8,000 employees is between 34 and 40 minutes."},{"key":"C","text":"Exactly 95% of all 8,000 employees have a commute time between 34 and 40 minutes."},{"key":"D","text":"If the study were repeated many times, exactly 95% of those studies would yield a sample mean of 37 minutes."}]$lyceon_json$::jsonb, 'B', NULL, E'The 95% confidence interval is $37 \\pm 3$, or 34 to 40 minutes, and it estimates the population mean. The researcher is 95% confident that the true mean commute time for all 8,000 employees falls in this interval. Saying 95% of the sampled employees have commute times in that range confuses a confidence interval for a mean with an interval for individual values. Saying exactly 95% of all employees have commute times in that range similarly mistakes an interval for a population mean as a range for individual data points. Claiming 95% of repeated studies would yield a sample mean of exactly 37 confuses confidence level with the probability of replicating the exact sample statistic.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UILWUC', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A machine fills $9$ bottles every $5$ minutes. At this rate, how many bottles does the machine fill in $35$ minutes?', NULL, $lyceon_json$[{"key":"A","text":"$45$"},{"key":"B","text":"$63$"},{"key":"C","text":"$70$"},{"key":"D","text":"$54$"}]$lyceon_json$::jsonb, 'B', NULL, E'The rate is $\\frac{9}{5}$ bottles per minute. In 35 minutes: $\\frac{9}{5} \\times 35 = 63$ bottles.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2V6JUUI', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'grid_in', E'A student records the following quiz scores: $73, 81, 88, 65, 93$. What is the median of these scores?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '81', ARRAY['81'], E'Arranging the scores in order gives $65, 73, 81, 88, 93$. With $5$ values, the median is the $3$rd value, which is $81$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2V9EVDY', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'What is the solution set of the equation $\\sqrt{5x - 1} = x - 3$?', NULL, $lyceon_json$[{"key":"A","text":"$\\{1\\}$"},{"key":"B","text":"$\\{10\\}$"},{"key":"C","text":"$\\{1, 10\\}$"},{"key":"D","text":"$\\{-1, -10\\}$"}]$lyceon_json$::jsonb, 'B', NULL, E'Square both sides: $5x - 1 = (x - 3)^2 = x^2 - 6x + 9$. Rearranging gives $x^2 - 11x + 10 = 0$, which factors as $(x - 1)(x - 10) = 0$, yielding $x = 1$ and $x = 10$. However, squaring can introduce extraneous solutions, so both must be checked in the original equation. For $x = 1$: $\\sqrt{5(1) - 1} = \\sqrt{4} = 2$, but $1 - 3 = -2$. Since $2 \\neq -2$, $x = 1$ is extraneous. For $x = 10$: $\\sqrt{5(10) - 1} = \\sqrt{49} = 7$, and $10 - 3 = 7$. This checks, so the only valid solution is $\\{10\\}$. The distractor $\\{1\\}$ results from selecting the extraneous root without verifying it. The distractor $\\{1, 10\\}$ results from failing to check either solution for extraneous roots. The distractor $\\{-1, -10\\}$ results from a sign error when solving the factored equation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VMIBE3', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'A right triangle has legs of length $6$ and $11$. What is the length of the hypotenuse?', NULL, $lyceon_json$[{"key":"A","text":"$\\sqrt{85}$"},{"key":"B","text":"$\\sqrt{157}$"},{"key":"C","text":"$17$"},{"key":"D","text":"$\\sqrt{145}$"}]$lyceon_json$::jsonb, 'B', NULL, E'By the Pythagorean theorem, $c^2 = 6^2 + 11^2 = 36 + 121 = 157$, so $c = \\sqrt{157}$. The value $\\sqrt{85}$ results from an arithmetic slip such as computing $11^2 = 49$ instead of $121$. The value $17$ comes from simply adding the two leg lengths, reflecting a fundamental misunderstanding of the Pythagorean theorem. The value $\\sqrt{145}$ arises from a computation error like using $6^2 = 24$ instead of $36$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2W2TJ6S', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'In triangle $DEF$, an exterior angle at vertex $F$ measures $131°$. If the measure of angle $D$ is $58°$, what is the measure, in degrees, of angle $E$?', NULL, $lyceon_json$[{"key":"A","text":"$49°$"},{"key":"B","text":"$63°$"},{"key":"C","text":"$73°$"},{"key":"D","text":"$122°$"}]$lyceon_json$::jsonb, 'C', NULL, E'By the exterior angle theorem, an exterior angle of a triangle equals the sum of the two non-adjacent interior angles. So $131° = 58° + \\text{angle } E$, giving angle $E = 131° - 58° = 73°$. The value $49°$ comes from finding the supplement of $131°$ ($180° - 131° = 49°$), which is the interior angle at $F$, not the requested angle. The value $63°$ results from an arithmetic slip such as computing $131° - 68°$. The value $122°$ arises from incorrectly subtracting $58°$ from $180°$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2W68T2Q', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A random sample of 400 registered voters in a city found that 54% support a proposed park expansion. The margin of error for this estimate is 4 percentage points. Which of the following is the best interpretation of this result?', NULL, $lyceon_json$[{"key":"A","text":"Exactly 54% of all registered voters in the city support the park expansion."},{"key":"B","text":"Between 50% and 58% of all registered voters in the city are plausibly estimated to support the park expansion."},{"key":"C","text":"Between 50% and 58% of the 400 sampled voters support the park expansion."},{"key":"D","text":"If the survey were repeated, exactly 54% of the new sample would support the park expansion."}]$lyceon_json$::jsonb, 'B', NULL, E'A margin of error of 4 percentage points means the plausible range for the true population proportion is $54\\% \\pm 4\\%$, which gives 50% to 58% of all registered voters. Stating exactly 54% ignores sampling variability entirely. Applying the interval to the sample rather than the population confuses the sample statistic with the parameter being estimated. Claiming a repeated survey would yield exactly 54% misunderstands that sample results vary from sample to sample.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2X1R564', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which expression is equivalent to $\\frac{9x^4 - 15x^3}{3x^2}$?', NULL, $lyceon_json$[{"key":"A","text":"$3x^2 - 5x$"},{"key":"B","text":"$9x^2 - 15x$"},{"key":"C","text":"$3x^4 - 5x^3$"},{"key":"D","text":"$3x^2 + 5x$"}]$lyceon_json$::jsonb, 'A', NULL, E'Divide each term in the numerator by $3x^2$: $\\frac{9x^4}{3x^2} = 3x^{4-2} = 3x^2$ and $\\frac{15x^3}{3x^2} = 5x^{3-2} = 5x$. Since the numerator has subtraction, the result is $3x^2 - 5x$. The distractor $9x^2 - 15x$ results from dividing only by $x^2$ without dividing the coefficients by $3$. The distractor $3x^4 - 5x^3$ results from dividing the coefficients by $3$ but failing to subtract exponents. The distractor $3x^2 + 5x$ results from incorrectly changing the subtraction sign to addition when dividing.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XNTPKT', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'mcq', E'A right circular cone has a base radius of $6$ inches and a slant height of $14$ inches. What is the volume of the cone, in cubic inches? (Volume of a cone: $V = \\frac{1}{3}\\pi r^2 h$.)', NULL, $lyceon_json$[{"key":"A","text":"$168\\pi$"},{"key":"B","text":"$48\\pi\\sqrt{10}$"},{"key":"C","text":"$144\\pi\\sqrt{10}$"},{"key":"D","text":"$8\\pi\\sqrt{10}$"}]$lyceon_json$::jsonb, 'B', NULL, E'First find the height using the Pythagorean theorem: $h = \\sqrt{14^2 - 6^2} = \\sqrt{196 - 36} = \\sqrt{160} = 4\\sqrt{10}$. Then $V = \\frac{1}{3}\\pi(6^2)(4\\sqrt{10}) = \\frac{1}{3}(36)(4\\sqrt{10})\\pi = 48\\pi\\sqrt{10}$. The value $168\\pi$ results from using the slant height directly as the height: $\\frac{1}{3}\\pi(36)(14) = 168\\pi$. The value $144\\pi\\sqrt{10}$ comes from forgetting to divide by $3$: $\\pi(36)(4\\sqrt{10}) = 144\\pi\\sqrt{10}$. The value $8\\pi\\sqrt{10}$ arises from using $r$ instead of $r^2$: $\\frac{1}{3}\\pi(6)(4\\sqrt{10}) = 8\\pi\\sqrt{10}$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XWDKYD', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'mcq', E'A linear function $h$ satisfies $h(3) = 32$ and $h(11) = -24$. For what value of $x$ does $h(x) = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{71}{10}$"},{"key":"B","text":"$\\frac{31}{4}$"},{"key":"C","text":"$\\frac{83}{14}$"},{"key":"D","text":"$\\frac{53}{7}$"}]$lyceon_json$::jsonb, 'D', NULL, E'The slope of $h$ is $\\frac{-24 - 32}{11 - 3} = \\frac{-56}{8} = -7$. Using point-slope form with $(3, 32)$: $h(x) = -7(x - 3) + 32 = -7x + 21 + 32 = -7x + 53$. Setting $h(x) = 0$: $-7x + 53 = 0$, so $x = \\frac{53}{7}$. The value $\\frac{71}{10}$ results from an arithmetic error when computing the intercept. The value $\\frac{31}{4}$ arises from incorrectly setting up the slope formula with the wrong denominator. The value $\\frac{83}{14}$ comes from using $\\frac{-56}{14}$ for the slope (doubling the denominator) and then solving with that incorrect slope.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XXJ3T6', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A health researcher records the daily water intake and the number of headaches per month for 130 adult volunteers over a 6-month period. The researcher finds that participants who drank more water tended to report fewer headaches. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"Drinking more water causes fewer headaches."},{"key":"B","text":"There is an association between water intake and headache frequency."},{"key":"C","text":"Participants who had fewer headaches chose to drink more water as a result."},{"key":"D","text":"The study proves that dehydration is the primary cause of headaches."}]$lyceon_json$::jsonb, 'B', NULL, E'This is an observational study because the researcher recorded naturally occurring behaviors without assigning treatments. Observational studies can establish associations but cannot establish causation. Claiming that drinking more water causes fewer headaches incorrectly infers causation from an observational design. Claiming the reverse causal direction (fewer headaches led to more water) is equally unsupported. Stating the study proves dehydration is the primary cause of headaches overstates the findings and asserts causation without experimental evidence.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XZ059Q', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'A school district wants to determine whether a new after-school tutoring program improves math scores. They randomly assign 90 students to participate in the tutoring program and 90 students to a control group that does not receive tutoring. After 12 weeks, the tutoring group''s average math score increased by 14 points, while the control group''s average increased by 5 points. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"The tutoring program caused approximately a 9-point greater increase in math scores compared to the control group."},{"key":"B","text":"Students who attend tutoring are naturally better at math, which explains the score difference."},{"key":"C","text":"The results suggest an association but cannot establish causation because this is an observational study."},{"key":"D","text":"The 9-point difference is due to the placebo effect since the control group knew they were not being tutored."}]$lyceon_json$::jsonb, 'A', NULL, E'Because students were randomly assigned to the tutoring and control groups, this is a randomized experiment. Random assignment controls for confounding variables, so a causal conclusion is appropriate: the tutoring program caused roughly a $14 - 5 = 9$-point greater increase. Claiming that tutoring students are naturally better at math ignores that random assignment balances pre-existing differences. Calling this an observational study is incorrect because the researcher actively assigned the treatment. Attributing the difference entirely to a placebo effect is speculative and does not address the measured score improvement from the experimental design.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YE5DMH', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'grid_in', E'In a right triangle, one acute angle measures $37°$. The side adjacent to this angle has length $19$. What is the length of the side opposite the $37°$ angle, to the nearest tenth? (Use $\\tan(37°) \\approx 0.7536$.)', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '14.3', ARRAY['14.3'], E'In a right triangle, $\\tan(37°) = \\frac{\\text{opposite}}{\\text{adjacent}}$. With the adjacent side equal to $19$: opposite $= 19 \\times \\tan(37°) = 19 \\times 0.7536 = 14.3184$. Rounded to the nearest tenth, this is $14.3$. A common error is using sine or cosine instead of tangent, or inverting the ratio to divide $19$ by $0.7536$ (approximately $25.2$), which gives the wrong side length.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YF1258', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'grid_in', E'What is the smaller of the two solutions to $x^2 - 11x + 28 = 0$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '4', ARRAY['4'], E'Factor the quadratic: $x^2 - 11x + 28 = (x - 4)(x - 7) = 0$. Setting each factor equal to zero gives $x = 4$ or $x = 7$. The smaller solution is $4$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YLYWHW', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'grid_in', E'A bookshop sells hardcovers for 17 dollars each and paperbacks for 9 dollars each. On a particular day, the shop sold a combined total of 23 books for a total of 279 dollars. How many paperbacks were sold that day?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '14', ARRAY['14'], E'Let $h$ be the number of hardcovers and $p$ be the number of paperbacks. The system of equations is $h + p = 23$ and $17h + 9p = 279$. From the first equation, $h = 23 - p$. Substituting into the second equation gives $17(23 - p) + 9p = 279$, which simplifies to $391 - 17p + 9p = 279$, so $-8p = -112$ and $p = 14$. Therefore $14$ paperbacks were sold, and $h = 23 - 14 = 9$ hardcovers. Verification: $17(9) + 9(14) = 153 + 126 = 279$ dollars.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Z3BPY5', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'mcq', E'A scatterplot shows the relationship between hours spent studying and test scores for $15$ students. The line of best fit has the equation $y = 4.7x + 52$, where $x$ is hours studied and $y$ is the predicted test score. According to the line of best fit, what is the predicted test score for a student who studies for $6$ hours?', NULL, $lyceon_json$[{"key":"A","text":"$56.7$"},{"key":"B","text":"$76.7$"},{"key":"C","text":"$80.2$"},{"key":"D","text":"$83.9$"}]$lyceon_json$::jsonb, 'C', NULL, E'Substituting $x = 6$ into the equation gives $y = 4.7(6) + 52 = 28.2 + 52 = 80.2$. The value $56.7$ results from adding $4.7$ to $52$ only once instead of multiplying by $6$. The value $76.7$ results from computing $4.7 \\times 6 = 24.7$ (an arithmetic slip in multiplication) and then adding $52$. The value $83.9$ comes from using $x = 6.8$ or computing $4.7 \\times 7 = 32.9$ and adding $52 - 1 = 51$, an equation setup error.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZM0HCJ', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'How many real solutions does the system of equations $y = x^2 - 6x + 11$ and $y = 2x - 1$ have?', NULL, $lyceon_json$[{"key":"A","text":"$0$"},{"key":"B","text":"$1$"},{"key":"C","text":"$2$"},{"key":"D","text":"$4$"}]$lyceon_json$::jsonb, 'C', NULL, E'Substitute the linear equation into the quadratic: $x^2 - 6x + 11 = 2x - 1$, which simplifies to $x^2 - 8x + 12 = 0$. The discriminant is $(-8)^2 - 4(1)(12) = 64 - 48 = 16 > 0$, so there are two distinct real solutions. Factoring confirms: $(x - 2)(x - 6) = 0$, giving $x = 2$ and $x = 6$. The answer $0$ reflects a misconception that a parabola and line cannot intersect. The answer $1$ reflects incorrectly concluding the discriminant equals zero (tangent case). The answer $4$ reflects an error such as counting each intersection point''s $x$- and $y$-coordinates separately.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW207BPG0', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'In 1937, the entomologist Evelyn Cheesman published a monograph documenting 137 previously unrecorded beetle species she had collected across the islands of New Caledonia during a solo expedition lasting nineteen months. Cheesman''s work was remarkable not only for its taxonomic scope but also for the conditions under which it was conducted: she traveled without institutional funding, relying instead on small grants from the Royal Geographical Society and the proceeds from her earlier popular science books. Her meticulous field notes, which cross-referenced each specimen''s altitude, host plant, and time of capture, set a standard for ecological data collection that her contemporaries in better-funded laboratories had not yet adopted.', $lyceon_json$[{"key":"A","text":"Cheesman's beetle monograph established new practices for ecological data collection despite her limited financial resources."},{"key":"B","text":"Cheesman's expedition to New Caledonia lasted nineteen months and resulted in the discovery of many beetle species."},{"key":"C","text":"The Royal Geographical Society funded most of Cheesman's entomological research throughout her career."},{"key":"D","text":"Cheesman's field notes were later adopted as a template by laboratories around the world."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage highlights two interconnected points about Cheesman: her taxonomic work was accomplished without substantial institutional funding, and her data-collection methods surpassed those of better-resourced contemporaries. The answer stating that her monograph established new practices despite limited finances captures both elements. The option focusing solely on the expedition''s duration and species count addresses only one detail without conveying the passage''s central emphasis on her methodological contribution. The option claiming the Royal Geographical Society funded most of her research misreads the passage, which says she received only small grants from them. The option about laboratories worldwide adopting her notes goes beyond what the passage states, which mentions only that contemporaries had not yet matched her standard.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20Y1P4Z', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'Which choice completes the text with the most logical and precise word or phrase?', E'Marine biologists studying the migration patterns of loggerhead sea turtles have found that the animals display a remarkable ability to navigate across vast stretches of open ocean. Even when displaced hundreds of miles from their usual routes, the turtles can ______ their original course with striking accuracy, suggesting they rely on the Earth''s magnetic field as an internal compass.', $lyceon_json$[{"key":"A","text":"resume"},{"key":"B","text":"fabricate"},{"key":"C","text":"abandon"},{"key":"D","text":"undermine"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes turtles that, after being displaced, return to their original navigational course. "Resume" means to begin again after an interruption, which precisely fits the context of returning to a course that was disrupted. "Fabricate" means to construct or invent something, typically something false, which is incoherent with returning to an existing route. "Abandon" means to give up entirely, which contradicts the passage''s claim that the turtles successfully return to their course. "Undermine" means to weaken or damage, which makes no sense applied to one''s own navigational course in this context.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW210K8RA', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'Which choice completes the text with the most logical and precise word or phrase?', E'In her 2019 monograph on Ottoman provincial administration, historian Elif Bayraktar argues that the decentralization policies adopted in the late seventeenth century were not signs of imperial weakness, as earlier scholars had claimed, but rather a deliberate strategy to ______ local elites by granting them formal authority they had already seized in practice.', $lyceon_json$[{"key":"A","text":"placate"},{"key":"B","text":"commemorate"},{"key":"C","text":"sequester"},{"key":"D","text":"replicate"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes a strategy of granting formal authority to local elites who had already taken power informally, which is a way to appease or pacify them. "Placate" means to calm or appease someone by making concessions, which fits the idea of formalizing power the elites already held as a conciliatory gesture. "Commemorate" means to honor or remember a past event, which is irrelevant to a political strategy aimed at managing local power holders. "Sequester" means to isolate or set apart, which contradicts the idea of engaging with elites by granting them authority. "Replicate" means to copy or reproduce, which makes no sense in the context of managing political relationships with local leaders.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW219L4TG', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'Which choice best describes the main idea of the text?', E'Researchers studying Polynesian navigation have long debated whether ancient wayfinders relied primarily on star positions or on ocean swells to maintain course during open-water voyages. A 2019 study led by oceanographer Kalani Reyes analyzed wave-refraction data from seventeen atolls in the Tuamotu Archipelago and concluded that experienced navigators could detect swell patterns deflected by islands up to forty-three nautical miles away — a range significantly greater than previously documented. Reyes argues that this finding shifts the scholarly consensus: rather than serving as a secondary backup to celestial navigation, swell-reading may have functioned as the primary orientation method during overcast periods that could last several consecutive days in the central Pacific.', $lyceon_json$[{"key":"A","text":"Ancient Polynesian navigators used both star positions and ocean swells but considered celestial methods more reliable."},{"key":"B","text":"A study's findings about the detectable range of swell patterns suggest that swell-reading played a more central navigational role than scholars had assumed."},{"key":"C","text":"The Tuamotu Archipelago's unique geography makes it the best location for studying ancient Polynesian navigation techniques."},{"key":"D","text":"Polynesian wayfinders could navigate exclusively by reading ocean swells without any reference to celestial cues."}]$lyceon_json$::jsonb, 'B', NULL, E'The passage centers on Reyes''s finding that swell patterns can be detected at greater distances than previously known and the resulting argument that swell-reading may have been a primary navigation method rather than a secondary one. The option describing how the study''s findings elevate swell-reading''s navigational role captures this central idea. The option stating that ancient navigators considered celestial methods more reliable reflects the older consensus the passage is challenging, not the passage''s own point. The option about the Tuamotu Archipelago being the best study location introduces a claim the passage never makes. The option asserting that wayfinders navigated exclusively by swells overstates the argument, which positions swell-reading as primary during overcast periods, not as the sole method.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"detail_misread"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW22B92QV', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The algorithm developed by computational biologist Soren Lindqvist, which cross-references genomic sequences from over 1,400 fungal species with environmental metadata collected across seventeen _______ has enabled researchers to predict which soil-dwelling fungi are most likely to produce novel antimicrobial compounds.', $lyceon_json$[{"key":"A","text":"biomes; has enabled"},{"key":"B","text":"biomes, and has enabled"},{"key":"C","text":"biomes, has enabled"},{"key":"D","text":"biomes; and has enabled"}]$lyceon_json$::jsonb, 'C', NULL, E'The sentence''s subject is "The algorithm developed by computational biologist Soren Lindqvist," and its main verb is "has enabled." The non-restrictive relative clause "which cross-references genomic sequences from over 1,400 fungal species with environmental metadata collected across seventeen biomes" is set off by paired commas. The comma after "biomes" correctly closes this non-restrictive clause and allows the main verb "has enabled" to follow. Using a semicolon after "biomes" is incorrect because "has enabled researchers to predict..." is not an independent clause—it is the main predicate of "The algorithm," and a semicolon would sever the subject from its verb. Inserting "and" after the comma ("biomes, and has enabled") pulls "has enabled" into the relative clause as a compound predicate coordinated with "cross-references," making the sentence read as though the algorithm "cross-references...and has enabled" within the relative clause. This leaves "The algorithm" with no main verb at all, producing a fragment. Using a semicolon followed by "and" ("biomes; and has enabled") combines two errors: the inappropriate semicolon and the non-standard semicolon-plus-conjunction construction.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW23HYSUS', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Behavioral ecologist Tomoko Fujisawa has documented that Japanese macaques in Yakushima''s highland forests spend nearly 23 percent of their waking hours grooming unrelated group members, a rate substantially higher than that observed in lowland populations of the same species. Fujisawa hypothesizes that the harsh highland winters create survival pressures that favor expanded cooperative networks beyond kin. _______ her long-term data indicate that highland macaques who received the most grooming from non-kin were not the individuals who reciprocated most frequently, but rather those who occupied central positions in the troop''s spatial hierarchy, complicating a straightforward reciprocity explanation.', $lyceon_json$[{"key":"A","text":"Furthermore,"},{"key":"B","text":"However,"},{"key":"C","text":"For instance,"},{"key":"D","text":"Accordingly,"}]$lyceon_json$::jsonb, 'B', NULL, E'Fujisawa''s hypothesis proposes that harsh winters favor expanded cooperation beyond kin, which would suggest grooming follows a cooperative-reciprocity logic. The sentence after the blank, however, reveals that grooming patterns correlate with spatial centrality rather than reciprocity, which complicates rather than supports the cooperative-network hypothesis. "However" correctly signals this complication. "Furthermore" would indicate an additional point that extends the same line of reasoning, but the new data challenge the hypothesis rather than reinforcing it. "For instance" would introduce a specific illustration of the hypothesis, but the data do not exemplify the hypothesis; they undercut it. "Accordingly" implies the data follow logically from the hypothesis, yet the finding about spatial hierarchy contradicts a simple reciprocity-based model.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW23VMZQP', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'While studying sediment cores extracted from a lake in northeastern _______ geochemist Priya Sengupta identified mineral deposits that corresponded to a previously undocumented volcanic eruption approximately 11,000 years ago.', $lyceon_json$[{"key":"A","text":"Mongolia, geochemist"},{"key":"B","text":"Mongolia; geochemist"},{"key":"C","text":"Mongolia. Geochemist"},{"key":"D","text":"Mongolia geochemist"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence begins with the dependent clause "While studying sediment cores extracted from a lake in northeastern Mongolia," which must be followed by a comma before the main clause beginning with "geochemist Priya Sengupta identified." The comma after "Mongolia" correctly separates the introductory dependent clause from the independent clause. Using a semicolon after "Mongolia" is incorrect because a semicolon joins two independent clauses, and "While studying..." is a dependent clause that cannot stand alone. Using a period after "Mongolia" is incorrect for the same reason: it would turn the dependent clause into a sentence fragment. Omitting all punctuation between "Mongolia" and "geochemist" produces a run-on error, fusing the introductory clause into the main clause without any separation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2465KR2', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which finding from the study, if true, would most directly undermine the team''s initial conclusion?', E'A team of archaeologists excavating a Bronze Age settlement near Lake Ohrid in North Macedonia concluded that the site''s inhabitants practiced year-round sedentary agriculture based on three lines of evidence: the density of carbonized emmer wheat seeds in storage pits, the presence of heavy quern stones unsuitable for transport, and the absence of migratory animal bone assemblages in middens. The team argued that these factors collectively rule out seasonal occupation and establish the settlement as one of the earliest permanent agricultural communities in the western Balkans.', $lyceon_json$[{"key":"A","text":"Isotopic analysis of the emmer wheat seeds reveals that they were harvested during two distinct seasons separated by approximately five months, consistent with both a spring and an autumn planting cycle."},{"key":"B","text":"Comparable quern stones have been found at sites in neighboring Albania that are confirmed to have been occupied only during summer months, with residents caching the stones before relocating for winter."},{"key":"C","text":"Pollen cores from Lake Ohrid's sediment show that the surrounding landscape transitioned from mixed forest to open grassland approximately two centuries before the settlement was established."},{"key":"D","text":"Radiocarbon dating of the storage pits indicates that the settlement was occupied for at least three hundred years, longer than most other Bronze Age sites in the region."}]$lyceon_json$::jsonb, 'B', NULL, E'The team''s conclusion rests on three pillars, one of which is that heavy quern stones are unsuitable for transport and therefore indicate permanent occupation. A finding that comparable quern stones were cached at seasonally occupied sites directly undermines this reasoning by showing that such stones do not necessarily indicate year-round settlement — residents could leave them behind and return. The finding about two harvest seasons actually supports rather than undermines year-round occupation, since it shows agricultural activity across multiple seasons. The pollen core finding about landscape transition concerns the environment before the settlement existed and does not address the question of seasonal versus permanent habitation. The radiocarbon dating finding about three hundred years of occupation addresses the settlement''s longevity but not whether it was occupied continuously throughout each year.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW24S05OM', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'A student is writing a brief report about a scientific discovery and wants to emphasize the practical significance of the finding. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW25V53TY', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'A student is writing a research summary for an academic audience and wants to highlight an unexpected limitation of the study''s methodology that qualifies its central finding. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW27H73N9', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding, if true, would most directly support the researchers'' hypothesis?', E'Marine biologists Hana Korvath and Dmitri Selenko hypothesize that the sudden decline of starfish populations along the Oregon coast between 2013 and 2016 was driven primarily by elevated sea-surface temperatures rather than by the sea star wasting disease pathogen alone. They note that regions with the highest recorded temperature anomalies experienced population losses roughly three times greater than regions where the pathogen was equally prevalent but temperatures remained near historical averages.', $lyceon_json$[{"key":"A","text":"Starfish in laboratory settings exposed to the wasting disease pathogen at elevated water temperatures died at significantly higher rates than those exposed to the pathogen at normal temperatures."},{"key":"B","text":"The sea star wasting disease pathogen was first identified along the Oregon coast in 2012, one year before the population decline began."},{"key":"C","text":"Starfish populations in Alaska, where sea-surface temperatures did not rise significantly, experienced a comparable decline during the same period."},{"key":"D","text":"Oregon's starfish populations had experienced a similar decline in the 1980s due to an unrelated bacterial infection."}]$lyceon_json$::jsonb, 'A', NULL, E'The researchers'' hypothesis is that elevated temperatures were the primary driver of starfish decline, beyond the pathogen alone. A laboratory finding showing that the pathogen causes higher mortality at elevated temperatures directly supports the claim that temperature amplifies the pathogen''s effect. The finding about the pathogen''s first identification in 2012 establishes timeline but does not address the role of temperature. The finding that Alaskan populations declined without temperature increases would actually undermine the hypothesis by showing decline can occur without the proposed driver. The finding about a 1980s decline from a different infection concerns a separate event and pathogen, providing no evidence about the temperature-pathogen interaction central to the hypothesis.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW27W0CT3', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'By the time volcanologist Sven Karstadt arrived at the monitoring station on Mount Pavlof in March 2024, seismic sensors _______ a steady increase in tremor activity for nearly eleven weeks.', $lyceon_json$[{"key":"A","text":"recorded"},{"key":"B","text":"have recorded"},{"key":"C","text":"had been recording"},{"key":"D","text":"were recording"}]$lyceon_json$::jsonb, 'C', NULL, E'The construction "By the time [past event], [clause]" requires the past perfect or past perfect progressive in the second clause to establish that the action began before and continued up to the reference point. Because the sensors were continuously recording for eleven weeks prior to Karstadt''s arrival, the past perfect progressive "had been recording" is the correct form: it conveys an ongoing action that started before a past reference point and continued up to it. The simple past "recorded" does not convey the ongoing, durational nature of the action indicated by "for nearly eleven weeks." The present perfect "have recorded" is incorrect because the narrative is set entirely in the past; present perfect links a past action to the present, which conflicts with the past-tense frame established by "arrived." The past progressive "were recording" does not properly establish the temporal priority required by "By the time"; it describes an action in progress at a past moment but does not convey that the action had already been continuing for a specific duration before the reference event.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW29I01VL', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which quotation from a literary scholar, if accurate, would most effectively support the claim presented in the text?', E'Some critics have argued that Nella Larsen''s 1929 novel Passing is primarily a study of racial identity in Jazz Age America. However, recent scholarship has reframed the novel as an exploration of economic anxiety, noting that the protagonist Irene Redfield''s deepest fears center not on racial exposure but on the potential loss of her upper-middle-class domestic stability.', $lyceon_json$[{"key":"A","text":"\"Larsen's depiction of Harlem's social gatherings reveals her keen interest in documenting the cultural achievements of the New Negro movement.\""},{"key":"B","text":"\"Irene's recurring fixation on her household finances, her children's schooling prospects, and her husband's medical practice income suggests that class preservation, not racial allegiance, is the engine of her anxiety throughout the novel.\""},{"key":"C","text":"\"Passing is best understood alongside other novels of the Harlem Renaissance that grapple with the psychological toll of racial code-switching.\""},{"key":"D","text":"\"Larsen's prose style, with its clipped sentences and restrained affect, owes a clear debt to the modernist techniques of writers like Ernest Hemingway.\""}]$lyceon_json$::jsonb, 'B', NULL, E'The text''s claim is that recent scholarship reframes Passing as an exploration of economic anxiety, with Irene''s fears centering on loss of class stability rather than racial exposure. The quotation identifying Irene''s fixation on household finances, schooling, and income as evidence that class preservation drives her anxiety directly supports this reframing. The quotation about Harlem''s cultural achievements and the New Negro movement addresses a different thematic reading unrelated to economic anxiety. The quotation placing the novel alongside others dealing with racial code-switching aligns with the older racial-identity interpretation the text says recent scholars have moved beyond. The quotation about Larsen''s prose style and Hemingway''s influence concerns literary technique, not the novel''s thematic content.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW29JF4A7', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'The fruit fly Drosophila melanogaster has long served as a model organism in genetics research, in part because its genome contains only four pairs of chromosomes. Yet this apparent simplicity is deceptive: recent work by Tanaka and colleagues (2021) has shown that a single Drosophila gene, Dscam1, can generate over 38,000 distinct protein variants through alternative splicing—more than the entire gene count of many vertebrates. The finding has forced geneticists to reconsider the relationship between genomic complexity and organismal complexity, acknowledging that gene count alone is an unreliable proxy for biological sophistication.', $lyceon_json$[{"key":"A","text":"It presents a widely held assumption, introduces a finding that complicates that assumption, and describes the resulting shift in scientific thinking."},{"key":"B","text":"It compares the genomes of two species and argues that one is more complex than the other."},{"key":"C","text":"It traces the historical development of a research technique and evaluates its current applications."},{"key":"D","text":"It describes an experimental procedure and then critiques the methodology used by the researchers."}]$lyceon_json$::jsonb, 'A', NULL, E'The text first establishes the assumption that Drosophila''s genome is simple (four chromosome pairs), then introduces the Dscam1 alternative splicing finding that complicates this assumption, and finally describes how geneticists have reconsidered the link between genomic and organismal complexity. This matches the structure of assumption, complicating evidence, and resulting intellectual shift. The claim that the text compares two genomes and argues one is more complex is a misreading: vertebrates are mentioned only as a point of reference for the scale of the splicing finding, not as subjects of a comparative argument. The claim that it traces historical development of a technique is wrong because the text discusses a conceptual assumption and an empirical finding, not the evolution of a method. The claim that it describes and critiques an experimental procedure is wrong because the text does not describe Tanaka''s methods and offers no methodological critique.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW29L7P22', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 2, 'mcq', E'Based on the texts, how would the author of Text 2 most likely characterize the approach described in Text 1?', E'Text 1: Archaeologist Renata Voss has proposed that the large-scale stone constructions found at Neolithic sites in the Scottish Orkney Islands were built primarily to serve as astronomical observatories. Voss points to the precise alignment of doorways and passageways with solstice sunrise positions as evidence that the builders possessed sophisticated knowledge of celestial cycles and designed these structures to track seasonal changes.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW29OEJ9B', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The urban planning commission recommended that the developer _______ the height of the proposed condominium tower by at least three stories, citing concerns about the building''s potential to obstruct sightlines from a nearby historic observatory.', $lyceon_json$[{"key":"A","text":"reduces"},{"key":"B","text":"reduce"},{"key":"C","text":"would reduce"},{"key":"D","text":"reducing"}]$lyceon_json$::jsonb, 'B', NULL, E'The verb "recommended" introduces a mandative subjunctive clause: "recommended that the developer [verb]." In Standard English, the mandative subjunctive requires the bare (uninflected) form of the verb, regardless of the subject''s person or number. Therefore "reduce" is correct. The third-person singular indicative "reduces" is incorrect in a mandative subjunctive clause; the subjunctive does not inflect for number. The conditional "would reduce" is non-standard in American English after verbs of recommendation, demand, or suggestion; the mandative subjunctive—not a modal construction—is required. The present participle "reducing" cannot serve as the finite verb of the "that" clause and produces a structurally incomplete clause.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2AB9AQ5', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 1, 'mcq', E'Based on the texts, how would the author of Text 2 most likely respond to the claim made in Text 1?', E'Text 1: Nutritionist Clara Mendez has advocated for mandatory front-of-package labeling that uses a simple color-coded system—green, yellow, and red—to indicate the overall nutritional quality of packaged foods. Mendez argues that such labels empower consumers to make healthier choices at the point of purchase without requiring them to interpret complex nutritional data.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2CD3ASY', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the function of the second paragraph in relation to the first?', E'Paragraph 1: Literary critic Marjorie Perloff has argued that the Language poets of the 1970s and 1980s—writers such as Charles Bernstein, Lyn Hejinian, and Ron Silliman—achieved their most radical formal innovations by treating the sentence, rather than the line or the image, as the fundamental unit of poetic composition. By disrupting conventional sentence logic through parataxis, non sequitur, and syntactic fragmentation, Language poetry forced readers to become active constructors of meaning rather than passive recipients of authorial intention.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2D0LHK6', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'In the early twentieth century, pianists performing Frédéric Chopin''s nocturnes typically employed a technique called tempo rubato — flexible rhythmic phrasing in which the melody hand slightly anticipates or delays notes while the accompaniment hand maintains strict time. Acoustic analysis of recordings from the 1920s and 1930s shows that elite pianists applied rubato asymmetrically, using far more delay than anticipation, with the longest delays occurring at phrase endings. By the 1970s, however, recordings reveal that rubato had become markedly more restrained, with delays and anticipations nearly equal in frequency and magnitude. Some musicologists attribute this shift to the influence of historically informed performance practice, which emphasized fidelity to the printed score. Yet this explanation is complicated by the fact that Chopin himself, in his teaching notes, explicitly instructed students to let the melody hand ________', $lyceon_json$[{"key":"A","text":"maintain strict synchronization with the accompaniment at all times to ensure rhythmic clarity."},{"key":"B","text":"linger behind the beat rather than rush ahead of it, suggesting that the asymmetric rubato of earlier recordings may have been closer to the composer's intent."},{"key":"C","text":"alternate unpredictably between anticipation and delay so that no two performances of the same nocturne would sound alike."},{"key":"D","text":"follow the accompaniment hand's tempo without deviation, confirming that the restrained style of later recordings was historically accurate."}]$lyceon_json$::jsonb, 'B', NULL, E'The passage sets up a tension: later performers became more restrained in the name of historical fidelity, yet this explanation is ''complicated by'' Chopin''s own teaching notes. The word ''yet'' signals that Chopin''s instructions contradicted the restrained approach. Since early recordings featured asymmetric rubato with more delay than anticipation, the logical completion is that Chopin instructed students to linger behind the beat — aligning his teaching with the older style and undermining the claim that restraint is historically faithful. The option about strict synchronization contradicts the entire concept of tempo rubato that the passage describes Chopin as teaching. The option about unpredictable alternation introduces randomness that the passage''s acoustic data does not support and that would not specifically complicate the historically informed performance explanation. The option about following the accompaniment without deviation would actually support the later restrained style rather than complicate it, contradicting the passage''s ''yet'' signal.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"detail_misread"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2DD582X', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the underlined sentence in the text as a whole?', E'Capuchin monkeys in Costa Rica''s Guanacaste province have been observed rubbing certain plants on their fur—a behavior scientists initially attributed to insect repellence. [underline]However, laboratory analysis of the plants most frequently selected revealed no measurable insecticidal properties.[/underline] Researchers now hypothesize that the behavior may serve a social signaling function, as the plant compounds produce a strong odor detectable by other members of the troop.', $lyceon_json$[{"key":"A","text":"It introduces evidence that challenges an earlier interpretation of the monkeys' behavior."},{"key":"B","text":"It provides an example of a research method commonly used in primate studies."},{"key":"C","text":"It summarizes the main conclusion the researchers reached about the monkeys."},{"key":"D","text":"It describes a limitation that prevented researchers from completing their study."}]$lyceon_json$::jsonb, 'A', NULL, E'The underlined sentence reports that lab analysis found no insecticidal properties in the selected plants, directly contradicting the initial hypothesis of insect repellence mentioned in the preceding sentence. This evidence challenges the earlier interpretation and motivates the new hypothesis about social signaling that follows. The claim that it provides an example of a common research method misidentifies the rhetorical role: the sentence''s function is to present a finding that undermines a hypothesis, not to illustrate methodology. The claim that it summarizes the researchers'' main conclusion is factually wrong—the main conclusion (social signaling) appears in the next sentence, not in the underlined one. The claim that it describes a limitation preventing completion misreads the passage; the study was not incomplete but rather led to an alternative hypothesis.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2EDKPDA', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The collection of rare manuscripts housed in the university''s eastern _______ a handwritten letter believed to have been composed by the philosopher Hypatia of Alexandria in the late fourth century.', $lyceon_json$[{"key":"A","text":"wing include"},{"key":"B","text":"wing includes"},{"key":"C","text":"wing are including"},{"key":"D","text":"wing have included"}]$lyceon_json$::jsonb, 'B', NULL, E'The subject of the sentence is "The collection," which is a singular noun. The prepositional phrase "of rare manuscripts housed in the university''s eastern wing" modifies "collection" but does not change the number of the subject. Because the subject is singular, the verb must also be singular: "includes" is the correct form. The plural verb "include" does not agree with the singular subject "collection"; students may be misled by the nearby plural noun "manuscripts," but the head of the subject is "collection." The progressive form "are including" is both plural (disagreeing with the singular subject) and stylistically inappropriate for a stative description of contents. The present perfect plural "have included" is likewise plural and disagrees with the singular subject.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2F7BBXY', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The Koryo Mycological Archive houses freeze-dried specimens of over 9,700 fungal species collected from temperate forests across eleven _______ its primary function is to preserve genetic material that could prove essential for developing antifungal treatments in the event of a global crop blight.', $lyceon_json$[{"key":"A","text":"countries, its"},{"key":"B","text":"countries; its"},{"key":"C","text":"countries its"},{"key":"D","text":"countries; and its"}]$lyceon_json$::jsonb, 'B', NULL, E'The sentence contains two independent clauses: "The Koryo Mycological Archive houses freeze-dried specimens...across eleven countries" and "its primary function is to preserve genetic material." A semicolon correctly joins two closely related independent clauses. Using a comma between "countries" and "its" creates a comma splice, which is a boundary error in Standard English because a comma alone cannot join two independent clauses. Omitting all punctuation between "countries" and "its" produces a run-on sentence that fuses two independent clauses with no separation. Using a semicolon followed by the coordinating conjunction "and" is non-standard: a semicolon replaces a conjunction, so pairing the two is redundant and incorrect.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2GIWG89', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'Which choice completes the text with the most logical and precise word or phrase?', E'Philosopher Kwame Anthony Appiah has cautioned that the concept of cultural identity, while politically useful, can become intellectually ______ when it leads people to treat fluid, contested traditions as though they were fixed natural categories—a tendency that, Appiah notes, paradoxically undermines the very pluralism that identity politics claims to defend.', $lyceon_json$[{"key":"A","text":"pernicious"},{"key":"B","text":"tangential"},{"key":"C","text":"unprecedented"},{"key":"D","text":"provisional"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes a concept that, while useful, can become harmful when it causes people to treat fluid traditions as fixed categories and thereby undermines pluralism. "Pernicious" means having a harmful effect, especially in a gradual or subtle way, which precisely captures the intellectual danger Appiah identifies. "Tangential" means only marginally relevant, but the passage argues the concept is centrally important—its problem is that it causes harm, not that it is irrelevant. "Unprecedented" means never done or known before, which describes novelty rather than the harmful quality the passage attributes to the misuse of identity concepts. "Provisional" means arranged or existing for the present only, which would suggest the concept is temporary rather than harmful—an entirely different criticism from the one Appiah makes.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2K1K2JJ', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'The Texas horned lizard can shoot a directed stream of blood from the corners of its eyes when threatened by predators. Researchers have found that canids such as coyotes and foxes are strongly repelled by this blood, shaking their heads and retreating after contact, while raptors such as hawks show no aversion to it whatsoever. Chemical analysis has revealed that the blood contains high concentrations of formic acid derivatives absorbed from the lizard''s diet of harvester ants. Since raptors swallow prey whole and have highly acidic digestive systems, while canids bite and chew their prey, tasting it extensively before swallowing, it is most likely that the blood-squirting defense is effective against canids because ________', $lyceon_json$[{"key":"A","text":"canids encounter the noxious chemical compounds through direct oral contact during their feeding process."},{"key":"B","text":"canids are generally more cautious predators than raptors and are more easily startled by unexpected behavior."},{"key":"C","text":"the formic acid derivatives are only toxic to mammals and have no physiological effect on birds."},{"key":"D","text":"raptors have evolved a specific immunity to formic acid that canids lack."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage establishes that canids bite and chew prey, tasting it extensively, while raptors swallow prey whole. Combined with the blood''s chemical noxiousness, the logical completion is that canids are repelled because their feeding method brings them into direct oral contact with the unpleasant compounds. The option about canids being more cautious predators introduces a behavioral claim unsupported by the passage, which attributes the difference to feeding mechanics, not temperament. The option claiming formic acid derivatives are only toxic to mammals goes beyond the evidence — the passage says raptors show no aversion, but this could be due to feeding method rather than biological immunity. The option about raptors evolving specific immunity similarly introduces an unsupported evolutionary claim when the passage''s own explanation centers on how each predator physically processes its food.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2LLSZHU', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best states the central claim of the text?', E'The philosopher Kwasi Wiredu has argued that certain concepts in Akan thought — such as the notion of ''sunsum,'' often translated as ''spirit'' — are systematically distorted when rendered into English because the target language presupposes a sharp matter-spirit dualism absent in Akan metaphysics. For Wiredu, the problem is not merely lexical but structural: English philosophical vocabulary encodes Cartesian assumptions so deeply that even careful translators inadvertently import a dualist framework, making Akan ideas appear more mystical than their original formulation warrants. Wiredu contends that this translational distortion has led Western commentators to classify Akan philosophy as a form of animism, obscuring its sophisticated quasi-materialist ontology. His proposed remedy — what he calls ''conceptual decolonization'' — involves developing philosophical terminology that does not default to European categorical oppositions.', $lyceon_json$[{"key":"A","text":"Wiredu maintains that English-language translation imposes a foreign metaphysical framework on Akan concepts, and he advocates creating terminology free of European categorical assumptions."},{"key":"B","text":"Wiredu believes that the Akan concept of sunsum is entirely materialist and has been deliberately mischaracterized by Western scholars."},{"key":"C","text":"Wiredu argues that all philosophical translation between unrelated languages inevitably produces distortions that cannot be corrected."},{"key":"D","text":"Wiredu proposes that Akan philosophy should be studied only through the Akan language to preserve its original meaning."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage presents Wiredu''s argument in two linked parts: first, that translating Akan concepts into English distorts them by imposing Cartesian dualism, and second, that the remedy is developing new terminology without European categorical oppositions. The option capturing both the structural distortion claim and the proposed terminological remedy reflects the full central claim. The option describing sunsum as entirely materialist and deliberately mischaracterized overstates the passage, which says ''quasi-materialist'' and attributes the distortion to structural features of English rather than to deliberate intent. The option claiming all philosophical translation inevitably produces uncorrectable distortions generalizes far beyond Wiredu''s specific argument about English and Akan. The option suggesting Akan philosophy should be studied only in Akan goes further than Wiredu''s actual proposal, which is to develop new terminology rather than to restrict study to one language.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2OHNHZK', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Economists studying the ''resource curse'' — the paradox that countries rich in extractable natural resources often experience slower economic growth than resource-poor countries — have traditionally attributed the phenomenon to institutional corruption and currency overvaluation (so-called Dutch disease). However, a 2021 longitudinal study by Amara Osei-Bonsu examining forty-seven mineral-exporting nations over six decades found that the resource curse manifests strongly only in countries that began large-scale extraction before establishing robust tax-collection bureaucracies. Countries that developed efficient tax systems prior to their resource booms — such as Botswana with diamonds and Norway with petroleum — largely avoided the curse. Osei-Bonsu argues that the critical variable is not resource wealth itself but the sequence of institutional development, because countries that fund government operations primarily through resource revenues rather than broad-based taxation ________', $lyceon_json$[{"key":"A","text":"tend to invest resource revenues in sovereign wealth funds that insulate their economies from commodity price fluctuations."},{"key":"B","text":"face reduced incentive to build the administrative capacity needed to tax citizens, which in turn weakens the accountability relationship between the state and its population."},{"key":"C","text":"are more likely to experience military coups because control of extraction sites becomes the primary path to political power."},{"key":"D","text":"generally maintain more stable exchange rates than countries that rely on diversified export portfolios."}]$lyceon_json$::jsonb, 'B', NULL, E'Osei-Bonsu''s argument hinges on the sequence of institutional development: countries that began extraction before building tax bureaucracies experience the curse, while those with pre-existing tax systems avoid it. The logical completion must explain why relying on resource revenues instead of taxation produces worse outcomes. The option about reduced incentive to build administrative and accountability structures logically connects resource-revenue dependence to institutional weakness, completing the causal chain. The option about sovereign wealth funds describes a strategy used by countries that avoided the curse (like Norway), which contradicts the direction of the argument about countries that lack prior institutional capacity. The option about military coups introduces a specific political consequence not established by the passage''s focus on bureaucratic and fiscal institutional development. The option about stable exchange rates contradicts the passage''s mention of Dutch disease (currency overvaluation) and does not follow from the argument about taxation sequence.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2OWP5TH', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 3, 'mcq', E'Which choice best describes a difference in how the authors of the two texts conceptualize the relationship between biodiversity and ecosystem stability?', E'Text 1: Ecologist Priya Narayanan argues that biodiversity functions as a form of ecological insurance: in species-rich ecosystems, the loss of any single species is buffered by functionally similar species that can expand to fill the vacated niche. Under this insurance hypothesis, biodiversity stabilizes ecosystem processes not because every species contributes something unique, but precisely because many species are partially redundant in function. It is this redundancy, Narayanan contends, that makes diverse ecosystems resilient to perturbation.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2QS2JMV', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'Architectural historian Priya Nagarajan argues that the load-bearing mudbrick walls of Çatalhöyük, a Neolithic settlement in modern Turkey, were deliberately rebuilt every 70 to 90 years, not because they had deteriorated but because each generation sought to ritually renew the household space. _______ excavation records show that the rebuilt walls often replicated the exact floor plan and hearth placement of the structures they replaced, a consistency Nagarajan interprets as evidence of intentional ceremonial continuity rather than practical necessity.', $lyceon_json$[{"key":"A","text":"In other words,"},{"key":"B","text":"By contrast,"},{"key":"C","text":"In support of this claim,"},{"key":"D","text":"Consequently,"}]$lyceon_json$::jsonb, 'C', NULL, E'Nagarajan makes a claim that walls were rebuilt for ritual purposes, not practical ones. The sentence after the blank presents excavation evidence (replicated floor plans and hearth placements) that bolsters this claim. "In support of this claim" correctly signals that the evidence serves to substantiate the preceding argument. "In other words" implies a restatement or paraphrase, but the second sentence introduces new physical evidence, not a rephrasing of the first. "By contrast" signals opposition, yet the evidence aligns with the claim rather than contradicting it. "Consequently" implies a cause-and-effect outcome, but the excavation records are presented as supporting evidence, not as a result caused by the rebuilding practice.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2RHTDLX', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'Geochemist Yael Kiro has studied the mineral deposits lining the shores of the Dead Sea for over a decade. Her analysis of aragonite layers revealed that the region experienced severe droughts approximately 120,000 years ago. _______ her findings suggest that the current decline in the Dead Sea''s water level may follow a pattern consistent with ancient climate cycles.', $lyceon_json$[{"key":"A","text":"Nevertheless,"},{"key":"B","text":"Specifically,"},{"key":"C","text":"Moreover,"},{"key":"D","text":"In contrast,"}]$lyceon_json$::jsonb, 'C', NULL, E'The second sentence describes one finding (ancient droughts), and the sentence after the blank adds a related finding (the current decline follows a similar pattern). The relationship is additive: the blank introduces an additional implication of the same research. "Moreover" correctly signals this additive relationship. "Nevertheless" wrongly implies a contrast or concession between the two sentences, but no contradiction exists. "Specifically" implies the third sentence narrows or elaborates a detail from the second, but the third sentence broadens the implications rather than specifying them. "In contrast" signals opposition, yet the two findings align rather than oppose each other.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2UFFK74', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'A student is writing about traditional textile arts and wants to present a contrast between historical and contemporary perceptions of the craft. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2X26LA2', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Literary scholar Emeka Osei-Mensah contends that Ama Ata Aidoo''s 1977 novel Our Sister Killjoy employs fragmented typography—irregular line breaks, shifts between prose and verse, abrupt changes in font size—not merely as aesthetic experimentation but as a deliberate formal strategy to mirror the protagonist''s psychological dislocation during her travels in Europe. Several critics have endorsed this reading, noting that the novel''s visual disruptions intensify during scenes of cultural alienation. _______ the same typographic irregularities also appear in passages depicting moments of intimate solidarity among Ghanaian characters, where no psychological dislocation is narrated, suggesting that Aidoo''s formal choices may serve a broader structural purpose that Osei-Mensah''s framework does not fully account for.', $lyceon_json$[{"key":"A","text":"That said,"},{"key":"B","text":"Similarly,"},{"key":"C","text":"To that end,"},{"key":"D","text":"In addition,"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage first presents Osei-Mensah''s claim (typographic fragmentation mirrors psychological dislocation) and notes critical endorsement. The sentence after the blank introduces a counterexample: the same techniques appear where no dislocation is present, implying the theory is incomplete. "That said" correctly signals a concessive turn—acknowledging the prior agreement while introducing a qualification. "Similarly" implies the new information parallels the preceding point, but it actually challenges it by showing the same formal features in non-dislocating contexts. "To that end" suggests the new information furthers the goal of the preceding argument, yet it undermines rather than advances Osei-Mensah''s reading. "In addition" signals a straightforward extension, but the new evidence does not simply add to the critical endorsement; it complicates the entire framework by revealing that typographic irregularity is not exclusive to scenes of alienation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2X2UETZ', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The effectiveness of the conservation strategies that the wildlife management board implemented across the seventeen wetland preserves it oversees in the lower Mississippi River _______ difficult to assess because comprehensive biodiversity surveys have not been conducted since 2019.', $lyceon_json$[{"key":"A","text":"basin are"},{"key":"B","text":"basin has been"},{"key":"C","text":"basin is"},{"key":"D","text":"basin were"}]$lyceon_json$::jsonb, 'C', NULL, E'The subject of the sentence is "The effectiveness," a singular noun. The long intervening clause "of the conservation strategies that the wildlife management board implemented across the seventeen wetland preserves it oversees in the lower Mississippi River basin" separates the subject from its verb but does not change its number. Because "effectiveness" is singular, the verb must be singular as well: "is" correctly agrees with the subject. The plural verb "are" does not agree with the singular subject "effectiveness"; students may be misled by the plural nouns "strategies," "preserves," or the compound-seeming phrase nearby, but the head noun remains "effectiveness." The singular present perfect "has been" introduces an unnecessary tense shift: the sentence describes a current state (the effectiveness is difficult to assess now because surveys have not been conducted), so the simple present "is" is appropriate rather than the present perfect. The past tense plural "were" is both wrong in number (plural rather than singular) and wrong in tense (past rather than present), since the difficulty of assessment is an ongoing condition linked to the present-tense clause "surveys have not been conducted since 2019."', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Z5E9BD', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The ceramic vessels recovered from the submerged trading post, which archaeologists believe functioned as a major hub for the exchange of spices and textiles between Polynesian and Melanesian _______ show distinctive glaze patterns not found in any other artifacts from the same historical period.', $lyceon_json$[{"key":"A","text":"traders; show"},{"key":"B","text":"traders. Show"},{"key":"C","text":"traders, show"},{"key":"D","text":"traders, and show"}]$lyceon_json$::jsonb, 'C', NULL, E'The sentence''s main subject is "The ceramic vessels recovered from the submerged trading post," and its main verb is "show." Between them, the non-restrictive relative clause "which archaeologists believe functioned as a major hub for the exchange of spices and textiles between Polynesian and Melanesian traders" is set off by commas. The comma after "traders" correctly closes this parenthetical relative clause and returns the sentence to its main verb "show." Using a semicolon after "traders" is incorrect because "show distinctive glaze patterns..." is not an independent clause—it is the main predicate of "The ceramic vessels," and a semicolon would sever the subject from its verb. Using a period after "traders" is likewise incorrect: "Show distinctive glaze patterns..." cannot stand alone as a sentence because it lacks a subject, producing a fragment. Inserting "and" after the comma ("traders, and show") incorrectly coordinates "show" with "functioned" inside the relative clause, making "show" part of what the trading post did rather than what the vessels do, and leaving the sentence without a main verb for its subject.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
